// coupled-subsystem simulation sketch for: Everything-Connected Systems Simulator
const subs = [
  {name:'power', x:0.574, k:0.086},
  {name:'thermal', x:0.432, k:0.152},
  {name:'structural', x:0.327, k:0.143},
  {name:'control', x:0.712, k:0.192},
  {name:'comms', x:0.748, k:0.183},
];
for (let t = 0; t < 60; t++) {
  for (const s of subs) { s.x += s.k * (1 - s.x) - 0.015 * s.x; }
}
const fin = subs.map(s => +s.x.toFixed(4));
console.log(JSON.stringify({subsystems: subs.length, steps: 60,
  finalState: fin, converged: fin.every(v => v > 0 && v < 1.5),
  topic: 'Everything-Connected Systems Simulator'}));

